inline constexpr std::size_t TABLE_COUNT = 14690;

// Binary-search lookup. Returns nullptr if id not in table.
inline const char* lookup(uint32_t id) noexcept {
    std::size_t lo = 0, hi = TABLE_COUNT;
    while (lo < hi) {
        std::size_t mid = lo + (hi - lo) / 2;
        if (TABLE[mid].id < id) lo = mid + 1;
        else hi = mid;
    }
    if (lo < TABLE_COUNT && TABLE[lo].id == id) return TABLE[lo].name;
    return nullptr;
}

